# Not listed, equivalent since SPEC 31.3a (2026-10-31): MD61, the `isinstance(a.get(k), str)` of the PISP match (review observation R3).
# An allowed element reaches the match only after its type check (each of legal_name, brand_name, domain_name a string),
# and C's pisp only after the closed schema check (the same three strings), so the isinstance is always true there. The
# line stays as a second guard.
# Not listed, equivalent on Python >= 3.11 (apc_ap2._iso): the fraction padded/cut to 6 digits. From 3.11
# datetime.fromisoformat reads any number of fraction digits, so the mutant changes nothing there; before 3.11 it
# reads only 3 or 6 and tests/test_review070.py kills it (independent review 25/10, m4_39.log on 3.9.25).


# Not listed, equivalent (apc_http.parse_exchange): `isinstance(st, bool)` in the status check. True and False are 1 and 0,
# both outside 100..599, so the range check refuses them anyway; the test stays as the grammar's own words.


# Not listed, equivalent (apc_ap2.es256_verify): the range check of r (1 <= r < n) and the reduction x mod n. The result
# is x mod n == r with x the affine x of u1 G + u2 Q: x mod n lies in [0, n), so r = 0 or r >= n never equals it
# except when x mod n is 0; and x differs from x mod n only when x >= n, which for P-256 (p - n < 2^129) happens with
# probability below 2^-127. Both checks stay, as FIPS 186-5 6.4.2 writes them.
# Not listed, equivalent in the verdict: the root_index bound in O2 (`idx < len(roots) or ...` replaced by True). With
# idx >= the number of roots, m = start + (idx+1)k >= seq + k >= n + k, so the next rule (m - n < k) fails: the result
# is failed either way, only the reason changes (review of 2026-10-23: 300 alterations, same verdict).
# Not listed, equivalent: O3 taking the block hash from the header's "hash" field instead of the recomputed hash. O3
# runs only when O2 is verified, and O2 is verified only when every header of the chain, the bundle's own included,
# has a hash field equal to its recomputed hash. Checked 2026-10-23 (tools/equiv_mutants.py ROOT o3 300): no difference on
# the 19 bundles of bundles/real_v03_canonical nor on 300 alterations of their header hash fields; a known
# non-equivalent mutant (the same, with the top header's hash field no longer compared by O2) differs on 188.
# Not listed, equivalent: the type check of `removed` inside _removed (`if not isinstance(lg["removed"], bool)`
# replaced by False). check_chain refuses a non-boolean `removed` on all three logs before anything else (SPEC 0.3.1),
# and every call of _removed (C2, C3, F1) runs after check_chain on the same chain_tx. Checked 2026-10-24: 191 bundles
# of bundles/, `removed` set to 11 values (absent, true, false, 0, 1, "true", "false", null, [], {}, 1.0) on each log
# present, 3883 cases: no difference; with the check_chain loop also removed (R10 on top) 2824 differ.
# Not listed, equivalent: _executed without its C1 condition (`return c2 == "verified" and ...`). On a direct call
# check_chain evaluates C2 only after C1 is verified, so C2 verified implies C1 verified; an indirect call takes the
# other branch. Checked 2026-10-24 (tools/equiv_x04.py ROOT): real bundles with a failed settlement reply and C1/C2
# broken six ways, 1152 cases, no difference; with C2 also dropped 235 differ.
# Not listed, equivalent: `{k: str(v).lower() ...}` in _reply (the 0.3.1 form): the hex check just before raises unless
# every member value is a str, so str(v) is v. Checked 2026-10-24 (independent review): wallet bundles with owner params fuzzed,
# 906 cases, no difference; the non-equivalent N06 differs on 62.


# Not listed, equivalent (independent review 27/10): NM02, apc-0.13 taken out of apc_verify.EVM_VERSIONS. apc_v1.verify copies the
# RPC members unchanged into an apc-0.3 bundle and calls _verify_bundle, which runs _no_upper_x on it: the verdict is
# refused either way, only the reason may differ. Checked: the 19 real_v03 bundles in v1 form, "0X" on each RPC leaf and
# 30 random pairs/triples each (probe equiv_nm02.py): no verdict differs; with the rule off for every version, differences.
# Not listed, equivalent: NM17, the keys of an object pushed one deeper in _no_surrogates. The depth test reads only
# dicts and lists, and a key of a parsed JSON object is a str. Checked: the 1036 corpus bundles and 3000 generated
# documents nested 55-70 deep, 0 differences; a non-equivalent control (values two deeper) differs on 1783.
# Not listed, equivalent: NM18, the logs' block compared with the receipt's instead of the transaction's in
# apc_authcap.chain_checks. The receipt is compared first under `or`: when it differs the condition holds either way,
# when it equals the two comparisons are the same. Checked on every assignment of 3 blocks to tx, receipt and 3 logs
# (243): 0 differences; the control without the receipt comparison differs on 6.


def run_tests(tree, mutated=""):
    env = dict(os.environ, HOME=os.path.dirname(tree), PYTHONDONTWRITEBYTECODE="1")
    env.pop("PYTHONPATH", None)
    r = subprocess.run([sys.executable, "-B", os.path.join("tools", "run_ordered.py"), mutated], cwd=tree, env=env,
                       capture_output=True, text=True)
    return r.returncode, r.stderr


FAILED_TEST = re.compile(r"^(?:FAIL|ERROR): \S+ \(.+\)$", re.M)


def verdict(rc, stderr):
    """killed = rc 1 and unittest names the failing test; SURVIVED = rc 0; anything else (a signal, a crash of the
    runner) is INVALID: the tests did not show the mutant wrong, so it does not count as killed."""
    if rc == 0:
        return "SURVIVED", ""
    m = FAILED_TEST.search(stderr)
    if rc == 1 and m:
        return "killed", m.group(0)
    return "INVALID(%d)" % rc, ""


def evidence(rc, stderr, t0, utc):
    """what the line keeps of a test run: the stderr from the line naming the failing test (or its end when there is
    none), 2000 characters at most, and the sha256 of the whole stderr"""
    m = FAILED_TEST.search(stderr)
    excerpt = stderr[m.start():m.start() + 2000] if m else stderr[-2000:]
    return {"rc": rc, "stderr_sha256": hashlib.sha256(stderr.encode()).hexdigest(), "stderr_excerpt": excerpt,
            "seconds": round(time.monotonic() - t0, 1), "utc": utc}


def utcnow():
    return datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def main():
    root, only = sys.argv[1], (sys.argv[2] if len(sys.argv) > 2 else "")
    # optional third argument "i/n": run only the mutants whose index modulo n is i (parallel shards; same control)
    shard = tuple(int(x) for x in sys.argv[3].split("/")) if len(sys.argv) > 3 else (0, 1)
    if "APC_SIGLIB" not in os.environ:
        print("set APC_SIGLIB (HOME is isolated)")
        return 64
    if not os.path.isfile(os.environ.get("APC_PULSE_CASES", "")):      # tests/test_ap2.py would skip its corpus
        print("set APC_PULSE_CASES (the pinned Pulse fixtures/v0.3/cases.json)")
        return 64
    # optional env APC_MUT_FIRST: a file of mutant names to run first (the new ones, so that a survivor shows early);
    # the order changes only which shard runs a mutant and when, not the set
    first = set(open(os.environ["APC_MUT_FIRST"]).read().splitlines()) if os.environ.get("APC_MUT_FIRST") else set()
    # optional env APC_MUT_SET: "first" runs only those names, "rest" only the others (two phases of one bench)
    part = os.environ.get("APC_MUT_SET", "")
    if part not in ("", "first", "rest"):
        print("APC_MUT_SET: first, rest or unset")
        return 64
    journal, done = None, {}
    if os.environ.get("APC_MUT_JOURNAL"):
        import bench_journal as bj
        try:
            siglib = os.environ["APC_SIGLIB"]
            journal = bj.Journal(os.environ["APC_MUT_JOURNAL"], {
                "tool": "mutants03", "tree": bj.tree_digest(root), "only": only, "shard": list(shard), "part": part,
                "first": sorted(first), "python": sys.version,
                "APC_SIGLIB": bj.tree_digest(siglib) if os.path.isdir(siglib) else bj.file_sha256(siglib),
                "APC_PULSE_CASES": bj.file_sha256(os.environ["APC_PULSE_CASES"])})
            done = journal.done("mutant")
            control = journal.done("control").get("control")
        except bj.JournalError as e:
            print("JOURNAL REFUSED:", e)
            return 3
        if control is not None:
            if control["rc"] != 0:
                print("CONTROL FAILED (recorded in the journal)")
                return 2
            print("control (unmutated copy) passes (recorded in the journal)", flush=True)
    if journal is None or control is None:
        tmp = tempfile.mkdtemp(prefix="m03_")
        try:
            shutil.copytree(root, os.path.join(tmp, "w"), ignore=shutil.ignore_patterns(".git", "__pycache__"))
            t0, utc = time.monotonic(), utcnow()
            rc, err = run_tests(os.path.join(tmp, "w"))
        finally:
            shutil.rmtree(tmp, ignore_errors=True)
        if journal is not None:
            journal.append("control", dict(evidence(rc, err, t0, utc), name="control"))
        if rc != 0:
            print("CONTROL FAILED", err[-300:])
            return 2
        print("control (unmutated copy) passes", flush=True)
    chosen = [m for m in sorted(M, key=lambda m: m[1] not in first)
              if not part or (m[1] in first) == (part == "first")]
    res = []
    for k, (f, name, old, new) in enumerate(chosen):
        if only not in name or k % shard[1] != shard[0]:
            continue
        if name in done:
            res.append((name, done[name]["verdict"]))
            print("%-40s %s (recorded in the journal)" % (name, done[name]["verdict"]), flush=True)
            continue
        src = open(os.path.join(root, f)).read()
        if src.count(old) != 1:
            res.append((name, "STALE(%d)" % src.count(old)))
            if journal is not None:
                journal.append("mutant", {"name": name, "verdict": res[-1][1], "count": src.count(old)})
            print("%-40s STALE(%d)" % (name, src.count(old)), flush=True)
            continue
        tmp = tempfile.mkdtemp(prefix="m03_")
        try:
            shutil.copytree(root, os.path.join(tmp, "w"), ignore=shutil.ignore_patterns(".git", "__pycache__"))
            mutated = src.replace(old, new)
            with open(os.path.join(tmp, "w", f), "w") as fh:
                fh.write(mutated)
            t0, utc = time.monotonic(), utcnow()
            rc, err = run_tests(os.path.join(tmp, "w"), f)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)
        st, failed = verdict(rc, err)
        res.append((name, st))
        if journal is not None:
            journal.append("mutant", dict(evidence(rc, err, t0, utc), name=name, verdict=st, failed_test=failed,
                                          mutated_sha256=hashlib.sha256(mutated.encode()).hexdigest()))
        print("%-40s %s" % (name, st), flush=True)
    alive = [n for n, s in res if s != "killed"]
    print("MUTANTS %d, killed %d, not killed %s" % (len(res), len(res) - len(alive), alive))
    return 1 if alive else 0


if __name__ == "__main__":
    sys.exit(main())
